using Nafadh_Backend.Enums;
using Nafadh_Backend.Models;
using Nafadh_Backend.Repositories;

namespace Nafadh_Backend.Services
{
    public class TraineePaymentScheduleService : ITraineePaymentScheduleService
    {
        private readonly ITraineePaymentScheduleRepository _repository;

        public TraineePaymentScheduleService(ITraineePaymentScheduleRepository repository)
        {
            _repository = repository;
        }

        public async Task<IEnumerable<NFD_TraineePaymentSchedule>>
          GetPaymentScheduleAsync(
          int traineePaymentId)
        {
            return await _repository
                .GetByPaymentIdAsync(traineePaymentId);
        }




        public async Task<IEnumerable<NFD_TraineePaymentSchedule>>
            GenerateInstallmentsAsync(
            int traineePaymentId,
            decimal totalAmount,
            int months)
        {

            var installmentAmount =
                totalAmount / months;


            var schedules =
                new List<NFD_TraineePaymentSchedule>();


            for (int i = 1; i <= months; i++)
            {

                schedules.Add(
                    new NFD_TraineePaymentSchedule
                    {
                        MonthNumber = i,

                        MonthLabel = $"Month {i}",

                        DueDate =
                            DateTime.Now.AddMonths(i),

                        Amount = installmentAmount,

                        Status =
                        NFD_PaymentScheduleStatus.Pending,

                        TraineePaymentId =
                            traineePaymentId
                    });
            }


            await _repository
                .AddRangeAsync(schedules);


            return schedules;
        }





        public async Task<bool>
            MarkAsPaidAsync(int id)
        {

            var schedule =
                await _repository.GetByIdAsync(id);


            if (schedule == null)
                return false;


            schedule.Status =
                NFD_PaymentScheduleStatus.Paid;


            schedule.PaidDate =
                DateTime.Now;


            await _repository.UpdateAsync(schedule);


            return true;
        }





        public async Task<IEnumerable<NFD_TraineePaymentSchedule>>
            GetOverdueAsync()
        {
            return await _repository
                .GetOverdueAsync();
        }

    }
}